    /** @var array<string,string> */
    private static array $memo = [];

    /** @var array<string,bool> icons referenced by the current page */
    private static array $used = [];

    /** When false (AJAX fragments, emails, invoices) icons are printed inline. */
    public static bool $sprite = true;

    public static function render(string $name, string $class = 'size-5', float $stroke = 1.6): HtmlString
    {
        $filled = isset(self::FILLED[$name]);
        if (! $filled && $name !== 'instagram' && ! isset(self::OUTLINE[$name])) {
            $name = 'info';
        }

        $cls = e($class);
        $attrs = $name === 'instagram'
            ? 'fill="none" stroke="currentColor" stroke-width="1.8"'
            : ($filled ? 'fill="currentColor"' : 'fill="none" stroke="currentColor" stroke-width="'.$stroke.'" stroke-linecap="round" stroke-linejoin="round"');

        if (self::$sprite) {
            self::$used[$name] = true;

            return new HtmlString('<svg class="'.$cls.'" '.$attrs.' aria-hidden="true"><use href="#i-'.$name.'"/></svg>');
        }

        $key = $name.'|'.$class.'|'.$stroke;

        return new HtmlString(self::$memo[$key] ??= '<svg class="'.$cls.'" viewBox="'.self::viewBox($name).'" '.$attrs.' aria-hidden="true">'.self::body($name).'</svg>');
    }

    /** The <symbol> sprite for every icon used on the page – printed once at the end of <body>. */
    public static function sprite(): HtmlString
    {
        if (! self::$used) {
            return new HtmlString('');
        }

        $out = '<svg xmlns="http://www.w3.org/2000/svg" style="display:none">';
        foreach (array_keys(self::$used) as $name) {
            $out .= '<symbol id="i-'.$name.'" viewBox="'.self::viewBox($name).'">'.self::body($name).'</symbol>';
        }

        return new HtmlString($out.'</svg>');
    }

    private static function viewBox(string $name): string
    {
        return isset(self::FILLED[$name]) ? self::FILLED[$name][0] : '0 0 24 24';
    }

    private static function body(string $name): string
    {
        if ($name === 'instagram') {
            return '<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none"/>';
        }

        return '<path d="'.(isset(self::FILLED[$name]) ? self::FILLED[$name][1] : self::OUTLINE[$name]).'"/>';
    }

    /** Icon names offered in the admin for feature/trust items. */
    public static function choices(): array
    {
        return [
            'truck' => 'Truck / Delivery', 'shield' => 'Shield / Genuine', 'refresh' => 'Return / Exchange',
            'cash' => 'Cash on Delivery', 'card' => 'Card / Payment', 'headset' => 'Support', 'chat' => 'Chat',
            'gift' => 'Gift', 'tag' => 'Price Tag', 'percent' => 'Discount', 'bolt' => 'Fast', 'clock' => 'Clock',
            'lock' => 'Secure', 'sparkles' => 'Quality', 'phone' => 'Phone', 'check-circle' => 'Check', 'heart' => 'Heart',
            'cube' => 'Package', 'fire' => 'Hot',
        ];
    }
